initJs:
function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let currentProducts = [];
  let selectedOrders = [];

  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
    window.aivicNotify?.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify?.success(message);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    // 業務ロジックでの期間バリデーション
    if (validateComparisonPeriod && startDate && endDate) {
      try {
        const isValid = validateComparisonPeriod(startDate, endDate);
        if (!isValid) {
          showError('指定された期間は無効です');
          return false;
        }
      } catch (error) {
        showError('期間バリデーションエラー: ' + error.message);
        return false;
      }
    }

    return true;
  }

  // 需要予測データを取得・分析
  async function getDemandForecast(productId, storeId, startDate, endDate) {
    try {
      // 売上データを収集
      const salesData = collectSalesData ? await collectSalesData(productId, storeId, startDate, endDate) : [];

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct ? classifySalesDataByProduct(salesData) : salesData;

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData ? filterValidProductData(productSalesData) : productSalesData;

      // 天候データを収集
      const weatherData = collectWeatherData ? await collectWeatherData(startDate, endDate) : [];

      // イベントデータを収集
      const eventData = collectEventData ? await collectEventData(startDate, endDate) : [];

      // 季節データを収集
      const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];

      // 相関分析
      let correlationResults = {};
      if (analyzeCorrelationSalesWeather) {
        correlationResults.weather = analyzeCorrelationSalesWeather(validProductData, weatherData);
      }
      if (analyzeCorrelationSalesEvent) {
        correlationResults.event = analyzeCorrelationSalesEvent(validProductData, eventData);
      }
      if (analyzeCorrelationSalesSeason) {
        correlationResults.seasonal = analyzeCorrelationSalesSeason(validProductData, seasonalData);
      }

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData ? 
        compareWithHistoricalData(validProductData, startDate, endDate) : null;

      return {
        salesData: validProductData,
        weatherData,
        eventData,
        seasonalData,
        correlationResults,
        historicalComparison
      };
    } catch (error) {
      showError('需要予測データの取得に失敗しました: ' + error.message);
      return null;
    }
  }

  // 発注データを読み込み
  async function loadOrderData() {
    try {
      const startDate = container.querySelector('#date-start')?.value;
      const endDate = container.querySelector('#date-end')?.value;
      const storeId = container.querySelector('#store-select')?.value;

      if (!validateDateRange()) return;

      const orders = await window.aivicApi.list(ORDER_TABLE, {
        startDate,
        endDate,
        storeId
      });

      currentProducts = orders || [];
      updateOrderTable();
      showSuccess('発注データを読み込みました');
    } catch (error) {
      showError('発注データの読み込みに失敗しました: ' + error.message);
    }
  }

  // 発注テーブルを更新
  function updateOrderTable() {
    const tbody = container.querySelector('#order-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    currentProducts.forEach((order, index) => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td><input type="checkbox" data-index="${index}"></td>
        <td>${order.productName || ''}</td>
        <td>${order.storeName || ''}</td>
        <td>${order.currentStock || 0}</td>
        <td>${order.forecastDemand || 0}</td>
        <td><input type="number" value="${order.orderQuantity || 0}" data-index="${index}" class="order-quantity"></td>
        <td>${order.orderDate || ''}</td>
        <td>
          <button class="btn-edit" data-index="${index}">編集</button>
          <button class="btn-delete" data-index="${index}">削除</button>
        </td>
      `;
      tbody.appendChild(row);
    });

    // チェックボックスのイベントリスナー
    tbody.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
      checkbox.addEventListener('change', handleOrderSelection);
    });

    // 発注数量変更のイベントリスナー
    tbody.querySelectorAll('.order-quantity').forEach(input => {
      input.addEventListener('change', handleQuantityChange);
    });

    // 編集・削除ボタンのイベントリスナー
    tbody.querySelectorAll('.btn-edit').forEach(btn => {
      btn.addEventListener('click', handleEditOrder);
    });
    tbody.querySelectorAll('.btn-delete').forEach(btn => {
      btn.addEventListener('click', handleDeleteOrder);
    });
  }

  // 発注選択処理
  function handleOrderSelection(event) {
    const index = parseInt(event.target.dataset.index);
    if (event.target.checked) {
      if (!selectedOrders.includes(index)) {
        selectedOrders.push(index);
      }
    } else {
      selectedOrders = selectedOrders.filter(i => i !== index);
    }
  }

  // 発注数量変更処理
  function handleQuantityChange(event) {
    const index = parseInt(event.target.dataset.index);
    const quantity = parseInt(event.target.value) || 0;
    if (currentProducts[index]) {
      currentProducts[index].orderQuantity = quantity;
    }
  }

  // 発注編集処理
  function handleEditOrder(event) {
    const index = parseInt(event.target.dataset.index);
    const order = currentProducts[index];
    if (!order) return;

    // 編集フォームに値を設定
    const productSelect = container.querySelector('#product-select');
    const storeSelect = container.querySelector('#store-select');
    const quantityInput = container.querySelector('#order-quantity');

    if (productSelect) productSelect.value = order.productId || '';
    if (storeSelect) storeSelect.value = order.storeId || '';
    if (quantityInput) quantityInput.value = order.orderQuantity || 0;

    // 編集モードフラグを設定
    container.dataset.editingIndex = index;
  }

  // 発注削除処理
  async function handleDeleteOrder(event) {
    const index = parseInt(event.target.dataset.index);
    const order = currentProducts[index];
    if (!order || !order.id) return;

    if (!confirm('この発注を削除しますか？')) return;

    try {
      await window.aivicApi.delete(ORDER_TABLE, order.id);
      currentProducts.splice(index, 1);
      updateOrderTable();
      showSuccess('発注を削除しました');
    } catch (error) {
      showError('発注の削除に失敗しました: ' + error.message);
    }
  }

  // 発注保存処理
  async function saveOrder() {
    try {
      const productId = container.querySelector('#product-select')?.value;
      const storeId = container.querySelector('#store-select')?.value;
      const quantity = parseInt(container.querySelector('#order-quantity')?.value) || 0;
      const orderDate = container.querySelector('#order-date')?.value;

      if (!productId || !storeId || quantity <= 0) {
        showError('必要な項目を入力してください');
        return;
      }

      const orderData = {
        productId,
        storeId,
        orderQuantity: quantity,
        orderDate: orderDate || new Date().toISOString().split('T')[0]
      };

      const editingIndex = container.dataset.editingIndex;

      if (editingIndex !== undefined) {
        // 更新
        const existingOrder = currentProducts[parseInt(editingIndex)];
        if (existingOrder?.id) {
          await window.aivicApi.update(ORDER_TABLE, existingOrder.id, orderData);
          currentProducts[parseInt(editingIndex)] = { ...existingOrder, ...orderData };
        }
        delete container.dataset.editingIndex;
      } else {
        // 新規作成
        const savedOrder = await window.aivicApi.save(ORDER_TABLE, orderData);
        currentProducts.push(savedOrder);
      }

      updateOrderTable();
      clearOrderForm();
      showSuccess('発注を保存しました');
    } catch (error) {
      showError('発注の保存に失敗しました: ' + error.message);
    }
  }

  // 一括発注処理
  async function bulkOrder() {
    if (selectedOrders.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    try {
      const orderPromises = selectedOrders.map(async (index) => {
        const order = currentProducts[index];
        if (!order) return;

        const orderData = {
          productId: order.productId,
          storeId: order.storeId,
          orderQuantity: order.orderQuantity,
          orderDate: new Date().toISOString().split('T')[0]
        };

        if (order.id) {
          return window.aivicApi.update(ORDER_TABLE, order.id, orderData);
        } else {
          return window.aivicApi.save(ORDER_TABLE, orderData);
        }
      });

      await Promise.all(orderPromises);
      selectedOrders = [];
      updateOrderTable();
      showSuccess('一括発注を完了しました');
    } catch (error) {
      showError('一括発注に失敗しました: ' + error.message);
    }
  }

  // フォームクリア
  function clearOrderForm() {
    const productSelect = container.querySelector('#product-select');
    const storeSelect = container.querySelector('#store-select');
    const quantityInput = container.querySelector('#order-quantity');
    const dateInput = container.querySelector('#order-date');

    if (productSelect) productSelect.value = '';
    if (storeSelect) storeSelect.value = '';
    if (quantityInput) quantityInput.value = '';
    if (dateInput) dateInput.value = '';
  }

  // 店舗・商品マスタを読み込み
  async function loadMasterData() {
    try {
      const [stores, products] = await Promise.all([
        window.aivicApi.list(STORES_TABLE),
        window.aivicApi.list(PRODUCTS_TABLE)
      ]);

      // 店舗セレクトボックスを更新
      const storeSelect = container.querySelector('#store-select');
      if (storeSelect && stores) {
        storeSelect.innerHTML = '<option value="">店舗を選択</option>';
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = store.name;
          storeSelect.appendChild(option);
        });
      }

      // 商品セレクトボックスを更新
      const productSelect = container.querySelector('#product-select');
      if (productSelect && products) {
        productSelect.innerHTML = '<option value="">商品を選択</option>';
        products.forEach(product => {
          const option = document.createElement('option');
          option.value = product.id;
          option.textContent = product.name;
          productSelect.appendChild(option);
        });
      }
    } catch (error) {
      showError('マスタデータの読み込みに失敗しました: ' + error.message);
    }
  }

  // イベントリスナーを設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#search-btn');
    if (searchBtn) {
      searchBtn.addEventListener('click', loadOrderData);
    }

    // 保存ボタン
    const saveBtn = container.querySelector('#save-btn');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrder);
    }

    // 一括発注ボタン
    const bulkOrderBtn = container.querySelector('#bulk-order-btn');
    if (bulkOrderBtn) {
      bulkOrderBtn.addEventListener('click', bulkOrder);
    }

    // クリアボタン
    const clearBtn = container.querySelector('#clear-btn');
    if (clearBtn) {
      clearBtn.addEventListener('click', clearOrderForm);
    }

    // 日付バリデーション
    const dateInputs = container.querySelectorAll('#date-start, #date-end');
    dateInputs.forEach(input => {
      input.addEventListener('change', validateDateRange);
    });

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', (event) => {
        const checkboxes = container.querySelectorAll('#order-table tbody input[type="checkbox"]');
        checkboxes.forEach(checkbox => {
          checkbox.checked = event.target.checked;
          handleOrderSelection({ target: checkbox });
        });
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadMasterData();
      setupEventListeners();

      // 初期日付設定
      const today = new Date().toISOString().split('T')[0];
      const startDateInput = container.querySelector('#date-start');
      const endDateInput = container.querySelector('#date-end');

      if (startDateInput && !startDateInput.value) {
        startDateInput.value = today;
      }
      if (endDateInput && !endDateInput.value) {
        const nextWeek = new Date();
        nextWeek.setDate(nextWeek.getDate() + 7);
        endDateInput.value = nextWeek.toISOString().split('T')[0];
      }

    } catch (error) {
      showError('初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
